# A simple check: does a suggested package actually exist on PyPI?
import urllib.request
import urllib.error

def package_exists(name):
    url = f"https://pypi.org/pypi/{name}/json"
    try:
        with urllib.request.urlopen(url, timeout=5) as resp:
            return resp.status == 200
    except urllib.error.HTTPError:
        return False   # 404 = package does not exist (possible hallucination)

# Before installing ANY AI-suggested package:
suggested = ["requests", "fast-json-parser", "numpy"]
for pkg in suggested:
    status = "REAL" if package_exists(pkg) else "DOES NOT EXIST - do not install!"
    print(f"{pkg}: {status}")
